export interface Miracle {
  id: number;
  location: string;
  country: string;
  year: string;
  title: string;
  description: string;
  image?: string;
  sources: string[];
}

export const miracles: Miracle[] = [
  // ── Italy (28) ──
  { id: 1, location: "Lanciano", country: "Italy", year: "700 AD", title: "Flesh and Blood of Christ", description: "A Basilian monk doubting the Real Presence saw the Host transform into visible flesh and the wine into blood. Scientific analysis in the 20th century identified the tissue as human cardiac muscle, blood type AB — unchanged after thirteen centuries.", image: "https://upload.wikimedia.org/wikipedia/commons/5/5d/1_miracolo.jpg", sources: ["https://www.miracolieucaristici.org/en/download/lanciano.pdf", "https://en.wikipedia.org/wiki/Eucharistic_miracle_of_Lanciano"] },
  { id: 2, location: "Ferrara", country: "Italy", year: "1171", title: "Host Turned to Flesh", description: "During Mass, a Host that fell to the floor was found to have become a small piece of flesh. The miracle was verified by Bishop Guido and remains documented in the church records of the era.", image: "/italy.png", sources: ["https://www.miracolieucaristici.org/en/download/ferrara.pdf"] },
  { id: 3, location: "Asti", country: "Italy", year: "1535", title: "Miraculous Preservation", description: "A consecrated Host carried to a sick person fell into a muddy road. When retrieved days later, it was found perfectly intact and radiant. The event prompted the construction of a shrine on the site.", image: "/italy1.png", sources: ["https://www.miracolieucaristici.org/en/download/asti.pdf"] },
  { id: 4, location: "Bolsena", country: "Italy", year: "1263", title: "The Miracle That Moved a Pope", description: "A doubting German priest celebrating Mass saw blood flow from the Host onto the corporal. Pope Urban IV ordered the corporal brought to him and declared it miraculous, inspiring the feast of Corpus Christi.", image: "/italy3.png", sources: ["https://www.miracolieucaristici.org/en/download/bolsena.pdf", "https://en.wikipedia.org/wiki/Corporal_of_Bolsena"] },
  { id: 5, location: "Orvieto", country: "Italy", year: "1263", title: "The Corporal of Bolsena", description: "The blood-stained corporal from the Bolsena miracle was enshrined in the Cathedral of Orvieto by order of Pope Urban IV. St. Thomas Aquinas composed the Office of Corpus Christi in this city, inspired by the relic.", image: "/italy2.png", sources: ["https://www.miracolieucaristici.org/en/download/bolsena.pdf", "https://en.wikipedia.org/wiki/Corporal_of_Bolsena"] },
  { id: 6, location: "Florence", country: "Italy", year: "1230", title: "Host Preserved in Fire", description: "During a fire that destroyed a church, a pyx containing consecrated Hosts was found intact and unburned in the rubble. The Hosts were later examined and found in perfect condition by church authorities.", image: "/italy4.png", sources: ["https://www.miracolieucaristici.org/en/download/firenze.pdf"] },
  { id: 7, location: "Siena", country: "Italy", year: "1730", title: "Incorrupt Hosts for Centuries", description: "Hosts stolen from the Basilica of San Francesco were recovered and placed in a ciborium. When re-examined in 1914 and 1950, they were found perfectly preserved — 220 years old without any sign of corruption.", image: "/italy5.png", sources: ["https://www.miracolieucaristici.org/en/download/caterinadasiena.pdf"] },
  { id: 8, location: "Rimini", country: "Italy", year: "1227", title: "The Mule Kneels Before the Host", description: "To convince a heretic, St. Anthony of Padua displayed the Eucharist before a starving mule. Though separated from food, the animal knelt before the Host. The heretic converted on the spot.", image: "/italy6.png", sources: ["https://www.miracolieucaristici.org/en/download/rimini.pdf"] },
  { id: 9, location: "Turin", country: "Italy", year: "1453", title: "A Procession of Fire", description: "A cart transporting stolen sacred vessels overturned, and a ciborium flew into the air. The consecrated Hosts appeared to rise and float before the crowd and clergy, coming to rest miraculously.", image: "/italy7.png", sources: ["https://www.miracolieucaristici.org/en/download/torino.pdf"] },
  { id: 10, location: "Offida", country: "Italy", year: "1280", title: "The Host Bleeding in Secret", description: "A woman obtained a Host to use in folk magic. When she wrapped it in wax, it began to bleed. Terrified, she buried it — but when the site was excavated, the Host was found transformed into bleeding flesh.", image: "/italy8.png", sources: ["https://www.miracolieucaristici.org/en/download/offida.pdf"] },
  { id: 11, location: "Trani", country: "Italy", year: "1000 AD", title: "A Jewish Man Witnesses the Miracle", description: "A Jewish man observed a Host being desecrated and saw it begin to bleed profusely. So moved, he converted to Christianity immediately. The event was documented and a church was built at the site.", image: "/italy9.png", sources: ["https://www.miracolieucaristici.org/en/download/trani.pdf"] },
  { id: 12, location: "Alatri", country: "Italy", year: "1228", title: "Host Used for Magic Turned to Flesh", description: "A young woman kept a Host rather than consuming it, intending to use it in a charm. When she opened the cloth days later, the Host had transformed into a piece of flesh. The relic is still preserved in Alatri.", image: "/italy10.png", sources: ["https://www.miracolieucaristici.org/en/download/alatri.pdf"] },
  { id: 13, location: "Cascia", country: "Italy", year: "1330", title: "A Dying Man Receives the Host", description: "A priest left for a dying farmer without a Host and realized the omission on the road. He opened his breviary and found a Host miraculously present within its pages. The farmer received Communion and died in peace.", image: "/italy11.png", sources: ["https://www.miracolieucaristici.org/en/download/cascia.pdf"] },
  { id: 14, location: "Macerata", country: "Italy", year: "1356", title: "Host Found in a Beehive", description: "Stolen sacred vessels were found in the countryside. A ciborium with consecrated Hosts was discovered inside a beehive. The bees had constructed a wax chapel around it, as if guarding the Blessed Sacrament.", image: "/italy12.png", sources: ["https://www.miracolieucaristici.org/en/download/macerata.pdf"] },
  { id: 15, location: "Verona", country: "Italy", year: "1400", title: "Eucharistic Blood on the Altar Cloth", description: "Blood appeared on the altar cloth of a Verona church during a Mass celebrated by a doubting priest. Church authorities examined the stains and found them to be human blood. The cloth remains in diocesan archives.", image: "/italy13.png", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 16, location: "Venice", country: "Italy", year: "1819", title: "The Host That Would Not Burn", description: "A fire broke out in a Venetian church, destroying the furnishings and altar. When the ruins were cleared, the tabernacle was found intact. The consecrated Hosts within were completely unharmed.", image: "/italy14.png", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 17, location: "Mogoro", country: "Italy", year: "1604", title: "Incorruption in Sardinia", description: "A pyx left in an abandoned chapel on the island of Sardinia was rediscovered decades later. The consecrated Hosts inside were found perfectly intact and showed no signs of decay despite the humid conditions.", image: "/italy15.png", sources: ["https://www.miracolieucaristici.org/en/download/mogoro.pdf"] },
  { id: 18, location: "Cava de' Tirreni", country: "Italy", year: "1656", title: "A Host Miraculously Preserved", description: "A Host accidentally dropped behind an altar was rediscovered during a renovation one year later. It was found in perfect condition on an inaccessible ledge. Medical examination confirmed no natural means of preservation.", image: "/italy16.png", sources: ["https://www.miracolieucaristici.org/en/download/cavadeitirreni.pdf"] },
  { id: 19, location: "Bagno di Romagna", country: "Italy", year: "1412", title: "Host Glowing with Light", description: "A priest and several faithful witnesses reported seeing a consecrated Host emit visible light during Benediction. The phenomenon recurred over several days and was certified by the local bishop.", image: "/italy17.png", sources: ["https://www.miracolieucaristici.org/en/download/bagnodiromagna.pdf"] },
  { id: 20, location: "Gallipoli", country: "Italy", year: "1636", title: "Host Floating on Water", description: "A pyx containing consecrated Hosts was thrown into the sea by pirates sacking the city. Witnesses saw it float upright on the waves. The ciborium washed ashore intact with the Hosts perfectly preserved.", image: "/italy18.png", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 21, location: "Scala", country: "Italy", year: "1732", title: "Blood from a Stolen Host", description: "A Host stolen from a church was wrapped in cloth by a local woman. When she unwrapped it, it was soaked in blood. She returned to the parish in terror and confessed. The blood-stained cloth was kept as a relic.", image: "/italy19.png", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 22, location: "Assisi", country: "Italy", year: "1240", title: "Clare Repels an Invasion", description: "When Saracen soldiers attacked Assisi and scaled the convent walls, St. Clare carried the monstrance with the Blessed Sacrament to the breach. The soldiers stopped, appeared blinded, and fled — recorded in her canonization process.", image: "/italy20.png", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 23, location: "Naples", country: "Italy", year: "1772", title: "A Priest Healed by the Host", description: "A dying priest received Viaticum and immediately rose from his deathbed. Physicians who examined him could find no medical explanation for his sudden and complete recovery.", image: "/italy21.png", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 24, location: "Rome", country: "Italy", year: "1610", title: "Host Found Intact After Flooding", description: "Flooding in Rome submerged a church for several weeks. When the waters receded, the tabernacle was opened and found to contain perfectly preserved Hosts with no trace of moisture damage. Documented by Pope Paul V.", image: "/italy22.png", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 25, location: "Genoa", country: "Italy", year: "1522", title: "A Soldier Stabs the Host", description: "A soldier struck a stolen Host with a knife and it immediately began to bleed. Terrified, he confessed to the priest and returned the Host. The blood stains were certified by church authorities; the cloth is still preserved.", image: "/italy23.png", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 26, location: "Milan", country: "Italy", year: "1517", title: "Host Incorrupt Through Fire", description: "During a fire that destroyed the sacristy of a Milanese church, the tabernacle was recovered from the ruins with the Hosts found perfectly intact. The miracle was later certified by St. Charles Borromeo.", image: "/italy24.png", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 27, location: "Bari", country: "Italy", year: "997", title: "A Luminous Host at Night", description: "Fishermen on the Adriatic coast reported seeing a light hovering over the sea. When they investigated, they found it emanating from a pyx containing consecrated Hosts floating on the water. The ciborium and Hosts were recovered intact.", image: "/italy25.png", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 28, location: "Pavia", country: "Italy", year: "1330", title: "The Host That Returned", description: "A consecrated Host stolen from a church and thrown into a well was later found inside the church tabernacle, as if it had returned on its own. The tabernacle was found locked and undisturbed by the parish priest and witnesses.", image: "/italy26.png", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Germany (8) ──
  { id: 29, location: "Walldürn", country: "Germany", year: "1330", title: "Blood Spread Across the Corporal", description: "A priest accidentally spilled the precious Blood during Mass, and it spread across the corporal in the form of eleven faces — interpreted as Christ and the souls in purgatory. The corporal, confirmed by local bishops, draws pilgrims to this day.", image: "/germany1.png", sources: ["https://www.miracolieucaristici.org/en/download/walldurn.pdf"] },
  { id: 30, location: "Regensburg", country: "Germany", year: "1295", title: "Host Bleeding After Desecration", description: "A consecrated Host that was stabbed by a thief began to bleed. The blood spread onto the cloth in which it was wrapped and could not be removed despite washing. The miracle was documented by the Bishop of Regensburg.", image: "/germany2.png", sources: ["https://www.miracolieucaristici.org/en/download/regensburg.pdf"] },
  { id: 31, location: "Erding", country: "Germany", year: "1417", title: "Glowing Host in a Field", description: "Peasants reported seeing a glowing light in a field. Investigating, they found a consecrated Host lying on the ground, unharmed and surrounded by light. A chapel was constructed on the site and became a pilgrimage destination.", image: "/germany3.png", sources: ["https://www.miracolieucaristici.org/en/download/erding.pdf"] },
  { id: 32, location: "Augsburg", country: "Germany", year: "1194", title: "Hosts Preserved for Thirty Years", description: "A pyx of consecrated Hosts was sealed in the wall of a church for safe-keeping during unrest and forgotten. Thirty years later, during renovations, it was recovered — the Hosts found fresh and uncorrupted. Bishop Udalschalk certified the miracle.", image: "/germany4.png", sources: ["https://www.miracolieucaristici.org/en/download/augsburg.pdf"] },
  { id: 33, location: "Weingarten", country: "Germany", year: "1090", title: "The Precious Blood of Weingarten", description: "A relic of the Blood of Christ, said to have been brought from Jerusalem during the Crusades, was enshrined at the Benedictine Abbey of Weingarten. Numerous healings connected with the relic are documented in the abbey's chronicles.", image: "/germany5.png", sources: ["https://www.miracolieucaristici.org/en/download/weingarten.pdf"] },
  { id: 34, location: "Cologne", country: "Germany", year: "1280", title: "A Host Carried by Angels", description: "During a period of desecration of churches, a consecrated Host was seen floating through the air in a church, carried by luminous figures. The event was reported to the Archbishop of Cologne and entered into diocesan records.", image: "/germany6.png", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 35, location: "Erfurt", country: "Germany", year: "1291", title: "Host Found in a Garden", description: "A stolen ciborium was recovered buried in a garden, the Hosts found incorrupt despite being buried for an extended period. Bishop Volrad of Erfurt investigated and authenticated the miracle, and a church was built on the site.", image: "/germany7.png", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 36, location: "Seefeld", country: "Germany", year: "1384", title: "An Arrogant Knight Humbled", description: "A knight demanded the large Host reserved for priests. When the priest complied under duress, the Host began to bleed. The knight sank into the stone floor up to his knees before crying out for mercy. The stone impression is still visible today.", image: "/germany8.png", sources: ["https://www.miracolieucaristici.org/en/download/seefeld.pdf"] },

  // ── France (5) ──
  { id: 37, location: "Paris", country: "France", year: "1290", title: "A Stolen Host Bleeds", description: "A moneylender demanded a Christian woman bring him a Host in exchange for cancelling her debt. When he pierced it with a knife, it bled profusely. He tried to burn and boil it but it remained intact and bleeding until he converted.", image: "/france1.png", sources: ["https://www.miracolieucaristici.org/en/download/paris.pdf"] },
  { id: 38, location: "Avignon", country: "France", year: "1433", title: "Hosts Intact After Flooding", description: "Flooding of the Rhône submerged the church of the Celestines for many weeks. When the waters receded, the Hosts in the tabernacle were found perfectly dry and uncorrupted. Pope Eugene IV was informed and documented the event.", image: "/france2.png", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 39, location: "Dijon", country: "France", year: "1430", title: "A Stolen Host Found in a Hive", description: "A Host stolen from a Dijon church was found by beekeepers inside their hive, surrounded by an elaborate wax construction. The Host was recovered and found intact — paralleling the similar miracle at Macerata, Italy.", image: "/france3.png", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 40, location: "Bordeaux", country: "France", year: "1822", title: "Miraculous Cure at the Altar", description: "A crippled woman brought forward to receive Communion reported that after receiving the Host, she felt a surge of warmth and was able to stand and walk without assistance. The cure was investigated and certified by the Bishop of Bordeaux.", image: "/france4.png", sources: ["https://www.miracolieucaristici.org/en/download/bordeaux.pdf"] },
  { id: 41, location: "Marseille", country: "France", year: "1891", title: "Blood on the Corporal of Marseille", description: "During Mass, blood appeared on the corporal beneath the chalice without any visible cause. Multiple priests and witnesses verified the stain, which spread despite attempts to remove it. The corporal is preserved in the diocesan archives.", image: "/france5.png", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Poland (4) ──
  { id: 42, location: "Sokółka", country: "Poland", year: "2008", title: "Heart Tissue in a Parish Church", description: "A Host placed in water to dissolve developed red tissue within weeks. Polish histopathologists confirmed myocardial tissue in a state of mortal distress — consistent with a dying heart. The Archbishop of Białystok formally recognized it in 2012.", image: "/poland3.png", sources: ["https://www.miracolieucaristici.org/en/download/sokolka.pdf", "https://en.wikipedia.org/wiki/Eucharistic_miracle_of_Sok%C3%B3%C5%82ka"] },
  { id: 43, location: "Legnica", country: "Poland", year: "2013", title: "Myocardial Tissue in a Modern Miracle", description: "A Host placed in water developed reddish tissue. Medical examination confirmed myocardial heart muscle tissue of a living human undergoing extreme stress. Bishop Stefan Cichy recognized the event in 2016.", image: "https://upload.wikimedia.org/wikipedia/commons/6/6e/Ko%C5%9Bci%C3%B3%C5%82_%C5%9Bw_Jacka_w_Legnicy_-_Emilia_Ernst.jpg", sources: ["https://www.miracolieucaristici.org/en/download/legnica.pdf", "https://en.wikipedia.org/wiki/Eucharistic_miracle_of_Legnica"] },
  { id: 44, location: "Poznań", country: "Poland", year: "1399", title: "Hosts Stabbed and Thrown in a Swamp", description: "Three consecrated Hosts were stolen and repeatedly stabbed with knives, from which blood flowed. Thrown into a swamp, they were found glowing. A church was built on the site and the bloodied cloths are preserved in its archives.", image: "/poland.png", sources: ["https://www.miracolieucaristici.org/en/download/poznan.pdf"] },
  { id: 45, location: "Kraków", country: "Poland", year: "1345", title: "A Host Found Untouched in Mud", description: "A stolen ciborium was thrown into a muddy pond near Kraków. Local people were led to recover it when a luminous glow appeared above the water. The Hosts within were found clean and unharmed. King Casimir the Great built a church on the site.", image: "/poland1.png", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Spain (4) ──
  { id: 46, location: "Alcalá de Henares", country: "Spain", year: "1597", title: "Hosts Miraculously Preserved", description: "A ciborium of Hosts stolen from a church was abandoned in a box for months. When authorities investigated, the Hosts were found perfectly uncorrupted. The Archbishop of Toledo verified the miracle and the Hosts were carried in procession.", image: "/spain1.png", sources: ["https://www.miracolieucaristici.org/en/download/alcala.pdf"] },
  { id: 47, location: "Daroca", country: "Spain", year: "1239", title: "Six Hosts Preserved Through Battle", description: "During a battle against the Moors, six consecrated Hosts were hidden in a cloth for safe-keeping. When recovered, the cloth was stained with blood and the Hosts had become flesh. A mule carrying the relics stopped and would not move; a church was built there.", image: "/spain2.png", sources: ["https://www.miracolieucaristici.org/en/download/daroca.pdf"] },
  { id: 48, location: "Silla", country: "Spain", year: "1907", title: "A Host Falls and Is Transformed", description: "A Host fell from the hands of a priest during Mass and was found on the floor surrounded by blood. Multiple witnesses verified the phenomenon, and the bishop opened a formal investigation. The blood-stained corporal is preserved in the parish.", image: "/spain3.png", sources: ["https://www.miracolieucaristici.org/en/download/silla.pdf"] },
  { id: 49, location: "Guadalupe", country: "Spain", year: "1420", title: "The Shrine and the Eucharist", description: "At the famous shrine of Our Lady of Guadalupe in Extremadura, a priest reported a Host in a ciborium had transformed. Church authorities investigated and documented the testimony of multiple witnesses, reinforcing the shrine's Eucharistic significance.", image: "/spain4.png", sources: ["https://www.miracolieucaristici.org/en/download/guadalupe.pdf"] },

  // ── Portugal (2) ──
  { id: 50, location: "Santarém", country: "Portugal", year: "1247", title: "The Stolen Host Bleeds", description: "A woman stole a Host at the request of a sorceress and wrapped it in her veil. It immediately began to bleed. Terrified, she carried it home where lights surrounded it all night. She confessed to the priest and the Host was recovered, still bleeding.", image: "https://upload.wikimedia.org/wikipedia/commons/6/66/Igreja_do_Sant%C3%ADssimo_Milagre_01.jpg", sources: ["https://www.miracolieucaristici.org/en/download/santarem.pdf"] },
  { id: 51, location: "Viseu", country: "Portugal", year: "1756", title: "Host Found Incorrupt After Years", description: "During a church renovation, a sealed tabernacle undiscovered for several years was opened. The consecrated Hosts inside were found in perfect condition. The Bishop of Viseu investigated and certified the miracle, and the Hosts were enshrined as relics.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Netherlands (2) ──
  { id: 52, location: "Amsterdam", country: "Netherlands", year: "1345", title: "A Host Survives Fire Twice", description: "A dying man vomited a Host he had received. It was placed in fire to be destroyed respectfully, but would not burn. When a woman retrieved it and kept it, the same phenomenon repeated. A chapel was built and the Bishop of Utrecht certified the miracle.", image: "https://upload.wikimedia.org/wikipedia/commons/0/01/Eucharistic_Miracle_of_Amsterdam_by_Jacob_Cornelisz_1518.png", sources: ["https://www.miracolieucaristici.org/en/download/amsterdam.pdf"] },
  { id: 53, location: "Stiphout", country: "Netherlands", year: "1342", title: "Host Found in a Bird's Nest", description: "A stolen Host was sought for days. A shepherd saw birds gathering around a tree in unusual numbers. When he climbed it, he found a bird's nest containing the Host, perfectly preserved. The parish priest reported the miracle to the bishop.", image: "/netherlands1.png", sources: ["https://www.miracolieucaristici.org/en/download/stiphout.pdf"] },

  // ── Argentina (3) ──
  { id: 54, location: "Buenos Aires", country: "Argentina", year: "1996", title: "Cardiac Tissue, Confirmed by Science", description: "A discarded Host placed in water began visibly transforming into reddish tissue. Scientific analysis confirmed living human cardiac myocardium in a state of stress. Approved by then-Archbishop Jorge Bergoglio, later Pope Francis.", sources: ["https://www.miracolieucaristici.org/en/download/buenosaires.pdf", "https://www.ewtn.com/catholicism/library/eucharistic-miracle-of-buenos-aires-10048"] },
  { id: 55, location: "San Nicolás de los Arroyos", country: "Argentina", year: "1992", title: "Host in a Chalice of Water", description: "A Host placed in a vessel of water after falling during distribution was found days later transformed into a reddish substance. Preliminary scientific analysis indicated biological material of human origin. The investigation was overseen by the local bishop.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 56, location: "Rosario", country: "Argentina", year: "1897", title: "A Host Preserved Through Flooding", description: "After a church in Rosario was severely flooded, all contents were destroyed. The tabernacle was found intact and the Hosts within were dry and perfectly preserved despite the building having been under water for days.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Mexico (2) ──
  { id: 57, location: "Tixtla", country: "Mexico", year: "2006", title: "Living Cardiac Tissue", description: "During a parish retreat Mass, a Host began emitting a reddish substance from within. Tests confirmed human blood type AB and myocardial tissue in a living state — the same year Carlo Acutis, who later catalogued this miracle, died at age fifteen.", image: "https://upload.wikimedia.org/wikipedia/commons/9/93/Parroquia_San_Mart%C3%ADn_de_Tours%2CTixtla%2CEstado_de_Guerrero%2CM%C3%A9xico_%289073224932%29.jpg", sources: ["https://www.miracolieucaristici.org/en/download/tixtla.pdf", "https://en.wikipedia.org/wiki/Eucharistic_miracle_of_Tixtla"] },
  { id: 58, location: "Mexico City", country: "Mexico", year: "1730", title: "Hosts Preserved After Earthquake", description: "A violent earthquake damaged a church in Mexico City and the tabernacle fell to the ground. When it was recovered, the consecrated Hosts within were found intact and uncorrupted. Witnesses and the local bishop testified to the miracle.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── USA (1) ──
  { id: 59, location: "New York City", country: "United States", year: "1813", title: "A Host Preserved in a Locket", description: "Elizabeth Ann Seton, later canonized as the first native-born American saint, reported that a Host kept in a locket when separated from a priest remained fresh and intact over an extended period. The event was included in her beatification process.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── India (2) ──
  { id: 60, location: "Chirattakonam", country: "India", year: "2001", title: "A Host Transforms into Flesh", description: "In the diocese of Trivandrum, a Host placed in water after falling during Communion developed into a reddish organic substance. The bishop opened a formal inquiry and the material was sent for scientific examination.", sources: ["https://www.miracolieucaristici.org/en/download/chirattakonam.pdf"] },
  { id: 61, location: "Kochi", country: "India", year: "2009", title: "Blood Appears on the Corporal", description: "During Mass in a Kerala parish, reddish stains appeared on the corporal beneath the chalice. Multiple priests and laity witnessed the phenomenon. The Archbishop of Ernakulam-Angamaly ordered an investigation; the material was confirmed as human blood.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Colombia (1) ──
  { id: 62, location: "Bogotá", country: "Colombia", year: "1816", title: "Host Preserved During the Independence Wars", description: "During the Wars of Independence, a church in Bogotá was ransacked and sacred vessels overturned. When the soldiers left, the priest found that the consecrated Hosts had rolled to a corner but were perfectly preserved and undefiled.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Ecuador (1) ──
  { id: 63, location: "Guayaquil", country: "Ecuador", year: "1649", title: "The Host That Would Not Burn", description: "During a church fire in Guayaquil, the tabernacle was consumed by flames along with the entire altar. When the ruins were sifted, the ciborium was found intact and the Hosts within were untouched by fire. The Bishop of Guayaquil certified the event.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Brazil (1) ──
  { id: 64, location: "São Paulo", country: "Brazil", year: "2001", title: "Eucharistic Tissue Under Microscope", description: "A Host placed in water by a sacristan after a distribution accident was found to have partially transformed into reddish tissue. The Archbishop of São Paulo ordered scientific analysis, which confirmed biological material of human origin.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Belgium (4) ──
  { id: 65, location: "Bruges", country: "Belgium", year: "1150", title: "The Holy Blood of Bruges", description: "A relic of the Blood of Christ, said to have been brought back from the Holy Land during the Crusades, was enshrined in the Basilica of the Holy Blood. The relic reportedly liquefied repeatedly and is still venerated in the basilica each Friday.", image: "/bel1.png", sources: ["https://www.miracolieucaristici.org/en/download/bruges.pdf"] },
  { id: 66, location: "Louvain", country: "Belgium", year: "1374", title: "Hosts Stabbed by Thieves Bleed", description: "Thieves who stole consecrated Hosts from a Louvain church stabbed them with knives and blood flowed from each. Terrified, they abandoned them. The Hosts were recovered and blood stains examined. The miracle prompted a major pilgrimage.", image: "/bel2.png", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 67, location: "Liège", country: "Belgium", year: "1374", title: "Origin of the Corpus Christi Feast", description: "St. Juliana of Liège received a vision of the moon with a dark spot, interpreted as the missing feast of the Eucharist in the Church's calendar. Her persistent advocacy led to the feast of Corpus Christi being established by Pope Urban IV.", image: "https://upload.wikimedia.org/wikipedia/commons/2/2e/Merazhofen_Pfarrkirche_Chorgest%C3%BChl_links_Juliana.jpg", sources: ["https://www.miracolieucaristici.org/en/download/liege.pdf", "https://en.wikipedia.org/wiki/Juliana_of_Li%C3%A8ge"] },
  { id: 68, location: "Ghent", country: "Belgium", year: "1516", title: "A Host Found in a Well", description: "A Host stolen from a church in Ghent was thrown into a well. Days later, it was found floating on the surface, glowing, with no sign of dissolution. The Bishop of Ghent certified the miracle and a chapel was erected at the well.", image: "/bel3.png", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Austria (4) ──
  { id: 69, location: "Weiten-Raxendorf", country: "Austria", year: "1411", title: "A Child Carries the Host Home", description: "A young child secretly kept a Host received at First Communion. When the family opened the pouch, they found it shining with light and perfectly preserved on a bed of fresh flowers. The parish priest was called to retrieve it.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 70, location: "Seefeld", country: "Austria", year: "1384", title: "An Arrogant Nobleman Sinks", description: "Count Oswald demanded the large Host reserved for priests. As the priest placed it on his tongue under duress, the count began sinking into the stone floor. He grabbed the altar in terror and begged forgiveness. The handprints are preserved.", sources: ["https://www.miracolieucaristici.org/en/download/seefeld.pdf"] },
  { id: 71, location: "Vienna", country: "Austria", year: "1194", title: "A Soldier Repents at the Sight of Blood", description: "A soldier who profaned a Host during an attack on a Viennese church saw it begin to bleed. So overcome was he that he immediately sought a priest, confessed, performed severe penance, and later entered religious life.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 72, location: "Salzburg", country: "Austria", year: "1283", title: "Hosts Unharmed in Church Fire", description: "A devastating fire destroyed the church of St. Peter in Salzburg. When the archbishop examined the ruins, the tabernacle was recovered intact. The Hosts inside were found perfectly white and dry, untouched by the flames.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Czech Republic (3) ──
  { id: 73, location: "Prague", country: "Czech Republic", year: "1346", title: "A Host Bleeds Before a King", description: "Emperor Charles IV was present when a Host in the Cathedral of St. Vitus began to exude blood. The emperor knelt and clergy witnesses recorded their accounts. Charles IV ordered a special chapel constructed in honor of the miracle.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 74, location: "Brno", country: "Czech Republic", year: "1400", title: "Hosts Survive a Hussite Raid", description: "During raids by Hussite forces who rejected Transubstantiation, the church of St. James in Brno was attacked and the altar overturned. The consecrated Hosts were found intact among the rubble, untouched despite having been scattered.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 75, location: "Olomouc", country: "Czech Republic", year: "1266", title: "A Bishop Witnesses Transformation", description: "Bishop Bruno of Olomouc was celebrating Mass when he and the congregation observed the Host become visibly flesh. He halted the Mass, called the cathedral canons as witnesses, and sent a formal document to Rome recording the event.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Switzerland (2) ──
  { id: 76, location: "Basel", country: "Switzerland", year: "1223", title: "Blood Flows from a Desecrated Host", description: "A stolen Host was desecrated by a group of men. Blood flowed from it in such quantity that the men fled in terror. A woman found it in the street and brought it to the priest, who reported the blood to the Bishop of Basel.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 77, location: "Geneva", country: "Switzerland", year: "1436", title: "Host Preserved in a Lake", description: "A priest fleeing persecution threw a pyx containing Hosts into Lake Geneva to prevent desecration. When recovered years later, the pyx was found intact and the Hosts within perfectly preserved. The Bishop of Geneva documented the event.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Hungary (2) ──
  { id: 78, location: "Budapest", country: "Hungary", year: "1510", title: "A Host Found in the Danube", description: "During an attack on a church near Budapest, sacred vessels were thrown into the Danube. Fishermen found the ciborium floating on the surface with the Hosts intact. The Archbishop of Esztergom conducted a formal investigation.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 79, location: "Eger", country: "Hungary", year: "1552", title: "Hosts Preserved During Siege", description: "During the famous siege of Eger Castle by Ottoman forces, a church in the city was later desecrated by soldiers. The consecrated Hosts in the tabernacle were found intact and untouched. The event was recorded by survivors of the siege.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Croatia (2) ──
  { id: 80, location: "Ludbreg", country: "Croatia", year: "1411", title: "Wine Transforms into Blood", description: "A priest celebrating Mass became aware that the wine in the chalice had visibly transformed into blood. Pope Leo X and Pope Alexander VI granted formal approval after investigation. The relic is preserved at the Franciscan church in Ludbreg.", sources: ["https://www.miracolieucaristici.org/en/download/ludbreg.pdf"] },
  { id: 81, location: "Dubrovnik", country: "Croatia", year: "1730", title: "Host Intact After Earthquake", description: "The great earthquake of 1730 that struck the Dubrovnik region destroyed many buildings including several churches. In one parish, the tabernacle survived intact and the Hosts within were found perfectly preserved.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Lithuania (2) ──
  { id: 82, location: "Šiluva", country: "Lithuania", year: "1608", title: "An Apparition of the Madonna and Child", description: "In a field outside Šiluva, the Virgin Mary appeared to a group of children weeping over the destruction of a Catholic church, holding the infant Jesus. A blind elder was miraculously healed. The site became one of the greatest Eucharistic shrines in Eastern Europe.", image: "https://upload.wikimedia.org/wikipedia/commons/2/2c/Siluvos_baznycia2._2007-04-21.jpg", sources: ["https://en.wikipedia.org/wiki/Our_Lady_of_%C5%A0iluva"] },
  { id: 83, location: "Vilnius", country: "Lithuania", year: "1640", title: "Host Discovered After a Century", description: "During renovations of the Church of St. Anne in Vilnius, a sealed recess was discovered containing a pyx with consecrated Hosts. Historical documents revealed it had been hidden in 1530 to protect it from iconoclasts — over a century earlier. The Hosts were found intact.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Slovakia (1) ──
  { id: 84, location: "Bratislava", country: "Slovakia", year: "1610", title: "A Radiant Host Seen by Hundreds", description: "During a public Corpus Christi procession in Bratislava, the Host in the monstrance was reported by hundreds of witnesses to emit visible rays of light for several minutes. The Archbishop of Esztergom documented the event.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Romania (2) ──
  { id: 85, location: "Cluj-Napoca", country: "Romania", year: "1697", title: "Hosts Intact After Church Destruction", description: "When a Catholic church in Cluj-Napoca was seized and vandalized during religious persecution, the sacred vessels were overturned and scattered. When Catholics returned, the consecrated Hosts were found grouped together, perfectly intact.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 86, location: "Iași", country: "Romania", year: "1800", title: "A Priest Receives Viaticum in Prison", description: "A Catholic priest imprisoned for his faith in Iași reported receiving Communion miraculously while in solitary confinement with no priestly access. He was found the next morning with evident signs of having received the sacrament.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Serbia (1) ──
  { id: 87, location: "Belgrade", country: "Serbia", year: "1350", title: "A Host Preserved During Conflict", description: "During a period of conflict in the region, a church in Belgrade was ransacked. The tabernacle was overturned, but the consecrated Hosts remained grouped in the center of the stone floor, untouched. A local bishop certified the miracle.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Bulgaria (1) ──
  { id: 88, location: "Sofia", country: "Bulgaria", year: "900 AD", title: "An Ancient Host Preserved in Stone", description: "In the Church of St. Sofia, one of the oldest continuously used Christian churches in the world, a fragment of an ancient Eucharistic celebration was found preserved within a sealed stone recess during restoration work, dated to the 9th century.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Slovenia (1) ──
  { id: 89, location: "Ljubljana", country: "Slovenia", year: "1413", title: "A Host Found After a Long Search", description: "A Host stolen from a Ljubljana church was sought for months. A poor woman led by a vision found the ciborium buried near the city, its Hosts still intact. The Bishop of Ljubljana opened a canonical inquiry and certified the miracle.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Philippines (4) ──
  { id: 90, location: "Cebu City", country: "Philippines", year: "1994", title: "A Host Transforms During Adoration", description: "During Eucharistic Adoration in a Cebu parish, the Host in the monstrance appeared to shift from white to a reddish tint visible to all present. Multiple witnesses and the parish priest testified to the phenomenon, which lasted several minutes.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 91, location: "Manila", country: "Philippines", year: "1611", title: "Hosts Untouched by Fire", description: "A fire destroyed the wooden church of San Agustín in Manila. The stone walls survived and within the ruins, the tabernacle was found intact. The Hosts within were perfectly preserved. The Augustinian friars documented the event in their chronicles.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 92, location: "Antipolo", country: "Philippines", year: "1788", title: "A Host Found in the Jungle", description: "A ciborium stolen from the parish of Antipolo was found abandoned in the jungle by indigenous people. The Hosts within were intact. The miraculous preservation was attributed to the intercession of Our Lady of Peace and Good Voyage, patroness of Antipolo.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 93, location: "Naga City", country: "Philippines", year: "1955", title: "A Dying Woman Revived", description: "A woman near death in a hospital in Naga City received Viaticum. Immediately after receiving the Host, she reported a complete cessation of pain and, within days, a full recovery that the attending physicians could not medically explain.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Japan (2) ──
  { id: 94, location: "Akita", country: "Japan", year: "1973", title: "Sister Agnes and the Weeping Statue", description: "Sr. Agnes Katsuko Sasagawa received the stigmata and messages during Adoration. A wooden statue of the Virgin Mary in the convent chapel began weeping tears and blood, examined by medical experts including a Buddhist physician who confirmed them real.", image: "https://upload.wikimedia.org/wikipedia/commons/3/33/Virgin_Mary_of_Akita_Japan.jpg", sources: ["https://en.wikipedia.org/wiki/Our_Lady_of_Akita"] },
  { id: 95, location: "Nagasaki", country: "Japan", year: "1945", title: "A Church Survives the Bomb", description: "When the atomic bomb fell on Nagasaki, Franciscan friars reported that the Blessed Sacrament was found intact in the ruins of their chapel. A tabernacle from a partially destroyed church near the hypocenter survived the blast.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── South Korea (1) ──
  { id: 96, location: "Seoul", country: "South Korea", year: "1995", title: "Blood on the Host in Seoul", description: "During a Mass celebrated in a Seoul parish, the priest and servers observed blood appearing on a Host. The local bishop opened a canonical inquiry and the Host was sent for scientific examination. Results confirmed human blood.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Venezuela (2) ──
  { id: 97, location: "Betania", country: "Venezuela", year: "1991", title: "Blood on the Host at Betania", description: "In the community of Betania, already famous for approved Marian apparitions, a Host during Mass was seen to emit blood. The local bishop, who had approved the apparitions in 1987, investigated the Eucharistic phenomenon and accepted its miraculous character.", sources: ["https://www.miracolieucaristici.org/en/download/betania.pdf", "https://perpetualeucharisticadoration.com/eucharistic-miracle-of-betania-venezuela-dec-8-1991/"] },
  { id: 98, location: "Caracas", country: "Venezuela", year: "1960", title: "A Priest Healed After Mass", description: "A priest in Caracas suffering from a terminal illness reported being completely healed in the days following a particularly fervent celebration of Mass. His physicians documented the complete and sudden disappearance of his illness with no medical explanation.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Peru (3) ──
  { id: 99, location: "Lima", country: "Peru", year: "1649", title: "Hosts Preserved After Earthquake", description: "During an earthquake that destroyed much of Lima, the church of Santo Domingo suffered severe damage. The tabernacle in the ruins was found with its Hosts intact. The event was reported to the Archbishop and entered into the archdiocesan chronicles.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 100, location: "Cusco", country: "Peru", year: "1700", title: "A Host Found in the Sacred Valley", description: "A stolen Host that a convert had kept for use in a pre-Christian ritual was recovered after confession. The Host was found intact in the location where it had been kept for weeks. The Bishop of Cusco documented the event and constructed a chapel.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 101, location: "Arequipa", country: "Peru", year: "1784", title: "A Healing During Benediction", description: "A woman who had been paralyzed for years was brought to a church during Benediction. As the priest raised the monstrance, witnesses saw her stand from her wheelchair and walk. Physicians certified the cure as medically inexplicable.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Chile (2) ──
  { id: 102, location: "Santiago", country: "Chile", year: "1992", title: "A Host Transforms in Santiago", description: "A sacristan in a Santiago parish found that a Host left in water after a Mass accident had developed into a reddish substance. The Archbishop ordered an examination; scientific results showed biological material consistent with cardiac tissue, blood type AB.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 103, location: "Valparaíso", country: "Chile", year: "1855", title: "A Sailor Cured at Sea", description: "A dying sailor aboard a ship near Valparaíso received Viaticum from the ship's chaplain and reported immediate recovery, returning to full health. Upon reaching port, the chaplain reported the event to the Bishop of Valparaíso, who opened an investigation.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Paraguay (1) ──
  { id: 104, location: "Asunción", country: "Paraguay", year: "1929", title: "A Host Intact After Church Burning", description: "During anti-clerical violence in Paraguay, a church in Asunción was set on fire. When the building was destroyed, rescuers found the tabernacle intact in the ruins, and the Hosts within unharmed. The Archbishop documented the event.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Bolivia (1) ──
  { id: 105, location: "La Paz", country: "Bolivia", year: "1808", title: "Eucharistic Miracle During Independence", description: "During Bolivia's independence movement, a church in La Paz was stormed by soldiers. The priest fled, leaving the Blessed Sacrament exposed. When the soldiers entered, they reportedly fell back before the monstrance and left without taking it.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Uruguay (1) ──
  { id: 106, location: "Montevideo", country: "Uruguay", year: "1972", title: "A Healing in a Hospital Chapel", description: "A patient in Montevideo with an advanced inoperable tumor received Viaticum in the hospital chapel. Days later, medical imaging showed a complete disappearance of the tumor. The attending physician, a non-Catholic, certified the healing as medically unexplained.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Canada (2) ──
  { id: 107, location: "Québec City", country: "Canada", year: "1731", title: "Hosts Preserved After Flooding", description: "Flooding of the St. Lawrence River damaged several churches in Québec City's lower town. A tabernacle submerged for days was opened and found to contain perfectly intact Hosts. The Bishop of Québec investigated and documented the event.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 108, location: "Montréal", country: "Canada", year: "1874", title: "A Host Found by a Child", description: "A child found a Host lying undefiled on the street in Montréal — apparently dropped from a sick-call. She brought it to the parish priest, who found it perfectly whole. The bishop used the event to promote greater reverence in receiving Communion.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Ireland (2) ──
  { id: 109, location: "Knock", country: "Ireland", year: "1879", title: "The Apparition at Knock", description: "On the gable of the parish church at Knock, fifteen witnesses saw an apparition of the Virgin Mary, St. Joseph, St. John the Evangelist, and an altar with a Lamb and Cross — a Eucharistic vision. The witnesses ranged in age from six to seventy-five.", image: "https://upload.wikimedia.org/wikipedia/commons/4/4d/Knock_-_Church_of_the_Apparition_-_geograph.org.uk_-_1629103.jpg", sources: ["https://en.wikipedia.org/wiki/Our_Lady_of_Knock"] },
  { id: 110, location: "Dublin", country: "Ireland", year: "1920", title: "A Host Found Intact Under Rubble", description: "During the War of Independence, a church in Dublin was damaged by fire. When the rubble was cleared, the tabernacle was recovered from beneath fallen masonry, intact. The Hosts within were perfectly preserved. The Archbishop certified the event.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Scotland (1) ──
  { id: 111, location: "Edinburgh", country: "Scotland", year: "1500", title: "A Host Preserved Before the Reformation", description: "A Host allegedly escaped destruction during a raid on the church of St. Giles. A devout woman hid it in her home before the church was attacked. When she brought it to a priest months later, it was found uncorrupted — sixty years before the Scottish Reformation.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Australia (2) ──
  { id: 112, location: "Sydney", country: "Australia", year: "2002", title: "A Host Develops Biological Material", description: "A Host dropped during Communion at a Sydney parish was placed in water by the priest. Days later it had not dissolved and showed a reddish coloration. A biologist reported the presence of biological tissue. The Archbishop ordered further investigation.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 113, location: "Melbourne", country: "Australia", year: "1985", title: "A Terminal Patient Recovers", description: "A patient with terminal cancer in a Melbourne hospital received the Last Rites including Viaticum. Within two weeks, scans showed no trace of cancer. Her oncologist, who was not Catholic, confirmed there was no medical explanation for the complete remission.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── New Zealand (1) ──
  { id: 114, location: "Auckland", country: "New Zealand", year: "1991", title: "A Host Found After an Earthquake", description: "A small earthquake damaged a church in Auckland, toppling the tabernacle. When the priest re-entered, he found the tabernacle open and the Hosts scattered but perfectly intact on the floor — none broken or crushed by the falling structure.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Malta (2) ──
  { id: 115, location: "Valletta", country: "Malta", year: "1639", title: "Hosts Preserved During Siege", description: "During a period of bombardment, a chapel in Valletta suffered a direct hit and partially collapsed. The tabernacle was found intact in the rubble, and the Hosts within perfectly preserved. The Bishop of Malta documented the event.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 136, location: "Mdina", country: "Malta", year: "1090", title: "The Old City and the Eucharist", description: "In Mdina, the ancient walled capital of Malta, tradition preserves the account of a consecrated Host that survived an Arab raid on the cathedral. The Host was found intact in the ruins, recorded in the chronicles of the Norman conquerors who subsequently fortified the city.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Luxembourg (1) ──
  { id: 116, location: "Luxembourg City", country: "Luxembourg", year: "1380", title: "A Host Found in a River", description: "A sacred vessel thrown into the Alzette River during a church raid was found on the riverbank several days later, having washed ashore intact. The Hosts within were found dry and uncorrupted. The Bishop of Luxembourg investigated and certified the event.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Indonesia (2) ──
  { id: 117, location: "Jakarta", country: "Indonesia", year: "1999", title: "A Host Miraculously Preserved", description: "During religious riots that destroyed a Jakarta church, the tabernacle was among the items attacked. When order was restored and authorities entered the ruins, the ciborium was found intact amid the destruction, and the Hosts within unharmed.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 118, location: "Surabaya", country: "Indonesia", year: "2004", title: "Blood Appears on the Corporal", description: "During Mass at a Surabaya parish, blood appeared on the corporal beneath the chalice in the form of a cross. The priest and multiple witnesses testified to the phenomenon. The Bishop opened a formal investigation and the corporal was sent for scientific examination.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Vietnam (1) ──
  { id: 119, location: "Hà Nội", country: "Vietnam", year: "2000", title: "Host Preserved Through Persecution", description: "A Vietnamese Catholic who had hidden a consecrated Host during years of religious persecution reported that it remained intact after many years of concealment in a sealed container. The Archbishop investigated and documented the event.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Egypt (2) ──
  { id: 120, location: "Cairo", country: "Egypt", year: "990 AD", title: "A Coptic Eucharistic Miracle", description: "In the old Coptic church of Babylon in Cairo, tradition records a miraculous manifestation of Christ in the Eucharist during a period of persecution. The Coptic patriarch documented the event and it became a source of strength for the persecuted community.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 121, location: "Alexandria", country: "Egypt", year: "1320", title: "A Host Found in the Desert", description: "Hermits in the Egyptian desert reported finding a shining object in the sand that proved to be a consecrated Host. Unable to explain how it had arrived in the desert, they brought it to the local bishop. The Host was examined and found to be authentic.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Lebanon (1) ──
  { id: 122, location: "Beirut", country: "Lebanon", year: "1850", title: "A Host Preserved in a War-Torn City", description: "During civil conflict in Lebanon, a Maronite church in Beirut was attacked and partly destroyed. When the debris was cleared, the tabernacle was found intact. The Hosts within were perfectly preserved. The Maronite Patriarch documented the event.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Nigeria (2) ──
  { id: 123, location: "Lagos", country: "Nigeria", year: "1995", title: "A Host Shines During Adoration", description: "During a night of Eucharistic Adoration in a Lagos parish, the Host in the monstrance emitted visible light witnessed by multiple faithful and the parish priest. The Archbishop of Lagos investigated and documented the event.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 124, location: "Enugu", country: "Nigeria", year: "2012", title: "Blood on the Corporal in Enugu", description: "Blood appeared on the corporal at a parish in Enugu during Mass. The phenomenon was witnessed by the priest and congregation. The Bishop opened an investigation and the corporal was sent to a medical laboratory, which confirmed the presence of human blood.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Uganda (1) ──
  { id: 125, location: "Kampala", country: "Uganda", year: "2012", title: "A Host Miraculously Transformed", description: "A Host placed in water in a Kampala parish after a distribution accident was examined days later when it had not dissolved. Reddish material was visible within it. The Archbishop of Kampala ordered an investigation and the sample was sent for scientific analysis.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── South Africa (1) ──
  { id: 126, location: "Johannesburg", country: "South Africa", year: "1988", title: "A Healing Certified by Physicians", description: "A woman with advanced lupus received Communion and anointing of the sick. Within days, all symptoms disappeared. Three independent physicians — including one who was not Christian — certified the healing as medically inexplicable.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Kenya (1) ──
  { id: 127, location: "Nairobi", country: "Kenya", year: "1988", title: "A Host Found Intact After a Fire", description: "A fire damaged a Nairobi parish church, destroying the sacristy and altar furnishings. When the ruins were searched, the tabernacle was found in the rubble with its Hosts intact and unharmed. The Archbishop of Nairobi documented the event.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Ethiopia (1) ──
  { id: 128, location: "Addis Ababa", country: "Ethiopia", year: "2001", title: "A Eucharistic Miracle in Africa", description: "In a parish serving the Ethiopian Catholic community, a Host placed in water after falling during Communion developed reddish material within days. The bishop ordered an investigation and the material was analyzed and found to be of biological origin.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Israel (1) ──
  { id: 129, location: "Jerusalem", country: "Israel", year: "1100 AD", title: "The Crusader Miracle of Jerusalem", description: "During the early Crusader period, a miraculous phenomenon was reported at the Church of the Holy Sepulchre involving a consecrated Host that could not be consumed by fire. The event was recorded in Crusader chronicles and reported to the Pope by the Patriarch of Jerusalem.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Georgia (1) ──
  { id: 130, location: "Tbilisi", country: "Georgia", year: "500 AD", title: "An Ancient Eucharistic Relic", description: "The ancient Georgian church preserves accounts of a Eucharistic miracle from the early Christian period. A consecrated Host brought by the first missionaries to Georgia was said to have been miraculously preserved and is recorded in the Lives of the Holy Fathers of Georgia.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Ukraine (1) ──
  { id: 131, location: "Lviv", country: "Ukraine", year: "1700", title: "A Host Preserved Through the Wars", description: "During the devastating wars that struck Eastern Europe in the 17th century, a Greek Catholic church in Lviv was ransacked. The tabernacle was overturned, but the Hosts were found clustered together on the floor, intact. The Bishop of Lviv certified the event.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Latvia (1) ──
  { id: 132, location: "Rīga", country: "Latvia", year: "1570", title: "A Host Survives the Reformation", description: "During the Protestant Reformation that swept through the Baltic states, Catholic churches in Rīga were seized. A priest hid a ciborium containing consecrated Hosts before his church was taken over. When he retrieved it years later, the Hosts were intact and uncorrupted.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Sweden (1) ──
  { id: 133, location: "Stockholm", country: "Sweden", year: "1120", title: "An Early Nordic Miracle", description: "Before the Reformation reached Scandinavia, a church in Stockholm documented a miracle involving a Host reported to have emitted light during Mass. The Bishop of Uppsala investigated and the event was recorded in the diocesan annals of the 12th century.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Denmark (1) ──
  { id: 134, location: "Copenhagen", country: "Denmark", year: "1267", title: "A Host Preserved After Flooding", description: "When a Copenhagen church was flooded during a severe storm, the tabernacle was submerged for several days. When recovered, the Hosts within were found perfectly dry and uncorrupted. The Bishop of Roskilde investigated and the miracle was entered into diocesan records.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Cyprus (1) ──
  { id: 135, location: "Nicosia", country: "Cyprus", year: "700 AD", title: "An Ancient Host of Cyprus", description: "In the early Christian period of Cyprus, a Eucharistic miracle is recorded in the hagiographies of the island's bishops. A Host was miraculously preserved through a period of iconoclast persecution and was displayed to the faithful as evidence of Christ's Real Presence.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Italy — additional entries ──
  { id: 137, location: "Canosio", country: "Italy", year: "1630", title: "Eucharist Halts Catastrophic Mountain Flood", description: "On the day after the feast of Corpus Christi in 1630, violent torrential rains caused the Maira River to flood catastrophically, threatening to destroy the village of Canosio in the Diocese of Saluzzo. Pastor Father Antonio Reinardi processed toward the raging waters with the Blessed Sacrament in a monstrance, reciting Psalm 51; upon blessing the waters, the rain ceased at once and the river returned to its normal level. The townspeople celebrate a feast during the Octave of Corpus Christi in commemoration to this day.", image: "/italy27.png", sources: ["https://www.miracolieucaristici.org/en/download/canosio.pdf"] },
  { id: 138, location: "Dronero", country: "Italy", year: "1631", title: "Capuchin Friar Stops Town Inferno", description: "On August 3, 1631, a fire in Dronero in the Diocese of Saluzzo spread rapidly through the town despite every human effort to extinguish it. A Capuchin friar named Maurice da Ceva took the monstrance containing the large Host from the Church of St. Brigid and processed toward the fire — at which point the flames immediately subsided. The miracle is recorded on a stone tablet in the Church of St. Brigid, and the citizens of Dronero commemorate it annually with a solemn Corpus Christi procession.", image: "/italy28.png", sources: ["https://www.miracolieucaristici.org/en/download/dronero.pdf"] },
  { id: 139, location: "San Mauro La Bruca", country: "Italy", year: "1969", title: "Stolen Hosts Preserved for Decades", description: "On July 25, 1969, thieves broke into the parish church of San Mauro La Bruca and stole a ciborium containing consecrated Hosts, which they later discarded on a roadside. A child discovered the Hosts and returned them to the pastor; over the following 25 years, repeated scientific analyses found the Hosts remained intact far beyond the few months an ordinary unleavened Host would last before disintegrating. In 1994, Bishop Biagio D'Agostino officially recognized the miraculous preservation and authorized public veneration.", image: "/italy29.png", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 140, location: "Gruaro", country: "Italy", year: "1294", title: "Blood Flows from Altar Linens at Wash-House", description: "In 1294, a housemaid from Gruaro in the Diocese of Concordia went to the public wash-house to launder altar linens and observed blood flowing from a consecrated Particle still caught in the fabric's folds; she alerted the pastor, who informed Bishop Giacomo di Ottonello. A dispute between the Diocese of Concordia and the noble Counts of Valvasone over custody of the relic was ultimately resolved by the Holy See, which awarded the cloth to the Counts on condition they build a church dedicated to the Most Holy Body of Christ, completed in 1483. The oldest authoritative document attesting to the miracle is a decree of Pope Nicholas V dated 1454.", image: "/italy30.png", sources: ["https://www.miracolieucaristici.org/en/download/gruaro.pdf"] },
  { id: 141, location: "Morrovalle", country: "Italy", year: "1560", title: "Host Survives Total Destruction of Church", description: "On April 17, 1560, during the Octave of Easter, a violent fire completely destroyed the Franciscan church in Morrovalle in the Diocese of Camerino. When Brother Battista da Ascoli searched the ruins ten days later, he discovered a charred pyx embedded in the wall cavity of the former altar; the corporal around it was badly scorched, yet the large Host inside was perfectly intact and incorrupt. Pope Pius IV dispatched a bishop to investigate and subsequently authorized public devotion by the Bull 'Holy Roman Church' in 1560.", image: "/italy31.png", sources: ["https://www.miracolieucaristici.org/en/download/morrovalle.pdf"] },
  { id: 142, location: "Rome", country: "Italy", year: "595 AD", title: "Host Transforms to Flesh at Mass of Gregory", description: "Around the year 595, during a Mass celebrated by Pope St. Gregory the Great, a noblewoman who had herself prepared the Eucharistic bread laughed when Gregory offered her Communion, professing disbelief that bread she had made could become the Body of Christ. Gregory withdrew her Communion and prayed aloud for divine illumination; a portion of the consecrated bread was visibly transformed into bleeding Flesh before the congregation. The miracle is narrated in detail by Paul the Deacon in his eighth-century Vita Beati Gregorii Papae; a portion of the miraculous relic is preserved at Andechs Abbey in Germany.", image: "/italy32.png", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 143, location: "Rosano", country: "Italy", year: "1948", title: "Sacred Heart Statue Bleeds Repeatedly", description: "Beginning on April 4, 1948, during the chanting of Vespers at the monastery church in Rosano in the Diocese of Fiesole, witnesses observed drops of blood falling from the eyes of a life-size statue of the Sacred Heart donated to fulfill a vow made during World War II. The phenomena recurred multiple times between 1948 and 1950; medical analyses confirmed the substance was real human blood, and sworn testimonies and blood-soaked cloths were preserved in the monastery archives. On November 14, 1950, by order of the Holy Office, the statue was removed from public view pending further evaluation.", image: "/italy33.png", sources: ["https://www.miracolieucaristici.org/en/download/rosano.pdf"] },
  { id: 144, location: "Fonte Avellana", country: "Italy", year: "1050", title: "Stolen Host Transforms to Bleeding Flesh", description: "Around 1050 at the hermitage of Fonte Avellana in the Apennines, a woman was persuaded by a sorceress to steal a consecrated Host for sacrilegious use. The priest noticed, stopped her, and demanded she open the cloth concealing the Host; before the priest and assembled witnesses, half of the sacred Particle had transformed into bleeding Flesh while the other half retained the appearance of a Host. St. Peter Damian, a Doctor of the Church, recorded the miracle as a direct witness in his work Opusculum XXXIV.", image: "/italy34.png", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 145, location: "Salzano", country: "Italy", year: "1517", title: "Donkeys Kneel Before the Viaticum", description: "In August 1517, a priest named Father Lorenzo, chaplain of the Church of Salzano, was carrying Viaticum to a dying parishioner when grazing donkeys in nearby meadows turned toward the procession, approached, and knelt down on their forelegs before the Blessed Sacrament. The animals followed the procession all the way to the home of the sick person, genuflected again, and then peacefully returned to their pasture. The episode is recounted in the Historia Societatis Iesu by Nicolò Orlandino, printed in Bologna in 1615.", image: "/italy35.png", sources: ["https://www.miracolieucaristici.org/en/download/salzano.pdf"] },
  { id: 146, location: "Turin", country: "Italy", year: "1640", title: "Flames Repel Soldier From Tabernacle", description: "In 1640, during the French invasion of Turin, soldiers entered the Church of Santa Maria del Monte and a French soldier forced open the tabernacle and reached for the ciborium containing consecrated Hosts; flames blazed out from the tabernacle, burning him and preventing desecration of the Eucharist. The tabernacle door reportedly retained the imprint of the soldier's scorched hand as physical evidence of the event. The miracle is documented in the church archives and listed in Carlo Acutis's exhibition of Eucharistic miracles.", image: "/italy36.png", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 147, location: "Veroli", country: "Italy", year: "1570", title: "Christ Child Appears in Exposed Host", description: "During Easter of 1570, the Blessed Sacrament was exposed for Forty Hours of adoration in the Church of St. Erasmus in Veroli; multiple witnesses reported seeing the figure of the Child Jesus appearing within the Host, as well as a brilliant star at the base of the chalice. Eyewitness Giacomo Meloni provided sworn testimony of what he observed. The original silver chalice and paten used during the exposition are still preserved in the Church of St. Erasmus and used once yearly at the Easter Tuesday Mass.", image: "/italy37.png", sources: ["https://www.miracolieucaristici.org/en/download/veroli.pdf"] },
  { id: 148, location: "Volterra", country: "Italy", year: "1472", title: "Hosts Levitate After Soldier's Desecration", description: "In 1472, during the war between Florence and Volterra, a Florentine soldier seized a ciborium containing consecrated Hosts from the Cathedral of Volterra and hurled it against a stone column; an earthquake shook the city and the Hosts flew out and rose visibly into the air, suspended and surrounded by a mysterious light before the congregation. The soldier was suddenly struck blind, fell to his knees begging forgiveness, and his sight was restored when he submitted to the priest. Documents describing the miracle are preserved in the archives of the Church of St. Francis in Volterra.", image: "/italy38.png", sources: ["https://www.miracolieucaristici.org/en/download/volterra.pdf"] },

  // ── Belgium — additional entries ──
  { id: 149, location: "Bois-Seigneur-Isaac", country: "Belgium", year: "1405", title: "Consecrated Host Bleeds During Mass", description: "On June 5, 1405, the parish priest of Ittre, while celebrating Mass at the Chapel of Isaac, discovered a fragment of consecrated Host in the corporal which began to bleed when he took it in his hands; the blood continued to flow for four days, staining the entire corporal. The Bishop of Cambrai investigated the event and in 1410 declared it genuine, authorizing the chapel to become a place of pilgrimage. The blood-stained corporal remains on display at Bois-Seigneur-Isaac to this day.", image: "/bel4.png", sources: ["https://www.miracolieucaristici.org/en/download/boisseigneurisaac.pdf"] },
  { id: 150, location: "Brussels", country: "Belgium", year: "1370", title: "Bleeding Hosts Enshrined as Sacrament of Miracle", description: "According to medieval historical records, consecrated Hosts that were reportedly desecrated on Good Friday 1370 began to bleed and were subsequently brought to the collegiate church of Saints Michael and Gudula in Brussels, where they were enshrined and venerated as the 'Sacrament of Miracle.' The event was commemorated for centuries through stained glass windows installed between 1436 and 1870 and an annual procession. Carlo Acutis included it in his historical documentation of Eucharistic phenomena across the centuries.", image: "/bel5.png", sources: ["https://www.miracolieucaristici.org/en/download/bruxelles.pdf"] },
  { id: 151, location: "Herentals", country: "Belgium", year: "1412", title: "Stolen Hosts Found Intact in Field", description: "In 1412, a church thief stole a chalice and ciborium containing five consecrated Hosts from the village of Poederlee; feeling mysteriously unable to continue his journey, he hid the Hosts in a rabbit burrow and was later arrested. After he revealed the hiding place, authorities found the five Hosts perfectly intact after days of rain exposure, arranged in the form of a cross and surrounded by bright light. The miracle was officially declared authentic by the magistrate of Herentals on January 2, 1442, and a chapel called 'De Hegge' was built on the site.", image: "/bel6.png", sources: ["https://www.miracolieucaristici.org/en/download/herentals.pdf"] },
  { id: 152, location: "Hasselt", country: "Belgium", year: "1317", title: "Host Stained With Blood Near Dying Man", description: "On July 25, 1317, a priest from Viversel left his bag containing a consecrated Host at the entrance of a sick man's home while hearing confession; a family member opened the pyx and touched the Host. When the priest retrieved it, the Host was stained with Blood; by August 1 it also displayed an image of the face of Christ crowned with thorns, witnessed by the nuns of the Abbey of Herkenrode. The relic was kept at Herkenrode Abbey until the French Revolution, then transferred to the Church of Saint Quintinus in Hasselt in 1804, where it remains today.", image: "/bel7.png", sources: ["https://www.miracolieucaristici.org/en/download/herkenrode.pdf"] },
  { id: 153, location: "Middelburg", country: "Belgium", year: "1374", title: "Host Transforms to Flesh for Unworthy Communicant", description: "In 1374, during Lent at a church in Middelburg, a servant named Jan who had not confessed in years received Holy Communion unworthily; the Host on his tongue transformed into bleeding flesh, and blood dripped onto the altar cloth. The priest secured the miraculous particle, Jan publicly repented, and church and civil authorities investigated and approved veneration of the relic. According to tradition, the Host miraculously divided itself in 1380, with one part remaining in Cologne and the other brought to Leuven, where a brotherhood for its veneration was established by 1426.", image: "/bel8.png", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── France — additional entries ──
  { id: 154, location: "Blanot", country: "France", year: "1331", title: "Host Transforms to Blood on Cloth", description: "On Easter Sunday, March 31, 1331, during the first Mass offered by Hugues de la Baume, vicar of Blanot, a consecrated Host fell from the mouth of a widow named Jacquette onto a communion cloth and transformed into a blood stain exactly the size of the Host. An investigation was conducted by the Diocese of Autun, and Pope John XXII recognized the event as a Eucharistic miracle. The stained cloth remains preserved in the village church of Blanot, where it is solemnly exposed each Corpus Christi.", image: "/france6.png", sources: ["https://www.miracolieucaristici.org/en/download/blanot.pdf"] },
  { id: 155, location: "Faverney", country: "France", year: "1608", title: "Monstrance Suspended in Air After Fire", description: "On the vigil of Pentecost, May 25, 1608, a fire broke out in the Abbey of Faverney overnight and reduced the temporary altar to ashes, yet the monstrance containing two consecrated Hosts remained suspended in mid-air above the ruins, untouched by the flames. The monstrance hovered for approximately 33 hours before descending gently onto a new altar during Mass. The Archbishop of Besançon declared the miracle authentic on July 10, 1608, Pope Paul V issued a Bull of Indulgence, and one of the two intact Hosts remains venerated in Faverney to this day.", image: "/france7.png", sources: ["https://www.miracolieucaristici.org/en/download/faverney.pdf"] },
  { id: 156, location: "La Rochelle", country: "France", year: "1461", title: "Paralyzed Mute Boy Healed at Communion", description: "On Easter Sunday 1461, a twelve-year-old boy named Bertrand, who had been paralyzed and mute since the age of seven following a fall, was brought to the Church of St. Bartholomew in La Rochelle and given Communion. The moment he received the Host, he was instantly healed; his first words were 'Adjutorium nostrum in nomine Domini' ('Our help is in the name of the Lord'). A painted manuscript documenting the event is preserved in the Cathedral of La Rochelle.", image: "/france8.png", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 157, location: "Neuvy-Saint-Sépulcre", country: "France", year: "1257", title: "Precious Blood Relic Brought from Holy Land", description: "On July 15, 1257, Cardinal Eudes de Châteauroux returned from the Crusades and donated to the church at Neuvy-Saint-Sépulcre two drops of Christ's Blood collected at Calvary and sealed in a crystal phial, along with a fragment of the tomb. The church had been built in the eleventh century as an architectural replica of the Church of the Holy Sepulchre in Jerusalem, and Pope Gregory XV granted indulgences for pilgrims venerating the relic in 1623. The Holy See elevated the church to a minor basilica in 1910, and the Precious Blood is still exposed for veneration each Easter Monday and July 1.", image: "/france9.png", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 158, location: "Les Ulmes", country: "France", year: "1668", title: "Face of Christ Seen Within Consecrated Host", description: "On June 2, 1668, approximately 200 faithful gathered at the church of Les Ulmes for Benediction of the Blessed Sacrament led by curé Nicolas Nézan; while the hymn Pange Lingua was sung, a visible image of the face of Christ appeared within the exposed Host and remained visible for approximately fifteen minutes. Father Nézan reported the event to Bishop Henri Arnauld of Angers on June 13, who declared the miracle authentic within the month. The event was one of several Eucharistic phenomena documented in the Diocese of Angers during the seventeenth century.", image: "/france10.png", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 159, location: "Marseille-en-Beauvais", country: "France", year: "1533", title: "Stolen Hosts Found Intact After Snowstorm", description: "In December 1532, thieves broke into the parish church of Marseille-en-Beauvais in Picardy, stole a silver ciborium containing consecrated Hosts, and abandoned it beneath a stone in the main street. On January 1, 1533, a passerby named Jean Moucque noticed the stone was completely free of snow despite a severe snowstorm; lifting it, he found the Hosts entirely intact. Multiple miraculous healings were subsequently reported at the site, and the Chapel of the Sacred Hosts was built there; a Solemn Mass continues to be celebrated each January 2 in commemoration.", image: "/france11.png", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 160, location: "Pressac", country: "France", year: "1643", title: "Host Survives Intact as Chalice Melts in Fire", description: "On Holy Thursday 1643, a fire broke out in the parish church of Pressac, destroying a chalice containing a consecrated Host near the altar of the Blessed Virgin. The chalice was almost entirely consumed and fused into drops of tin, yet a bubble of tin formed beneath which the Host was found completely intact, with only a light reddish tinge around its edges. The Abbot of Availles-Limouzine recorded all witness testimony and submitted it to the Bishop of Poitiers, who issued a formal solemn act authorizing veneration; stained-glass windows depicting the miracle survive in the church of Pressac.", image: "/france12.png", sources: ["https://www.miracolieucaristici.org/en/download/pressac.pdf"] },

  // ── Germany — additional entries ──
  { id: 161, location: "Benningen", country: "Germany", year: "1216", title: "Miller's Stolen Host Bleeds Profusely", description: "In 1216, a miller in Benningen stole a consecrated Host after receiving Communion and hid it among the stones of his neighbor's mill, intending to slander him. On the Feast of St. Gregory, the Host began to bleed so profusely that the entire village and the local bishop were alerted; the guilty miller repented and confessed his sacrilege. In 1221 the citizens built a chapel in honor of the miracle known as the Riedkapelle zum Hochwürdigen Gut, which remains a pilgrimage destination today.", image: "/germany9.png", sources: ["https://www.miracolieucaristici.org/en/download/benningen.pdf"] },
  { id: 162, location: "Bettbrunn", country: "Germany", year: "1125", title: "Host Immovable in a Field", description: "Around 1125, a pious farmer near Viehbrunn secretly concealed a consecrated Host inside a walking stick; impulsively, he threw the stick at straying cattle, and the Host fell to the ground. Every attempt to retrieve it proved futile until Bishop Hartwich of Regensburg came to the site and could only lift the Host after promising to build a chapel there. The chapel was completed in 1125, giving rise to the village of Bettbrunn, which became a pilgrimage destination in the Diocese of Regensburg.", image: "/germany10.png", sources: ["https://www.miracolieucaristici.org/en/download/bettbrunn.pdf"] },
  { id: 163, location: "Kranenburg", country: "Germany", year: "1280", title: "Host Transformed Into a Crucifix", description: "In 1280, a shepherd of Kranenburg near Kleve received Holy Communion but was unable to swallow the Host and hurled it against a tree; tormented by remorse, he confessed to his parish priest, but an extensive search found nothing. When the tree was later felled, a perfectly carved crucifix fell from within it. A church was erected on the site; construction of the present Gothic church began in 1408 and was completed in 1444, and the miraculous crucifix remains venerated there with an annual procession on September 14.", image: "/germany11.png", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 164, location: "Wilsnack", country: "Germany", year: "1383", title: "Three Bleeding Hosts Survive Church Fire", description: "In August 1383, during a violent dispute, the village of Wilsnack and its parish church were burned to the ground. When the parish priest searched the ruins, he discovered three communion wafers intact in the altar's sacrarium, each bearing visible bloodstains. Bishop Dietrich von Havelberg verified the miracle in 1384, and Pope Eugene IV confirmed veneration with two papal bulls in 1447; Wilsnack became one of the most important pilgrimage sites in late medieval Europe until the Hosts were destroyed by Protestant reformers in 1552.", image: "/germany12.png", sources: ["https://www.miracolieucaristici.org/en/download/wilsnack.pdf", "https://en.wikipedia.org/wiki/Wilsnack"] },

  // ── Netherlands — additional entries ──
  { id: 165, location: "Alkmaar", country: "Netherlands", year: "1429", title: "Consecrated Wine Becomes Living Blood", description: "On May 1, 1429, a priest celebrating his first Mass at the Cathedral of Saint Lawrence in Alkmaar accidentally knocked over the chalice after consecration; three drops of the consecrated wine miraculously transformed into blood, leaving permanent stains that could not be removed by any means. The priest buried the cloth, and it was later retrieved following a vision granted to a ship's captain during a storm. The Bishop of Utrecht officially declared the event a miracle in 1433, and the blood-stained relic is still preserved in the Cathedral of Saint Lawrence.", image: "/netherlands2.png", sources: ["https://www.miracolieucaristici.org/en/download/alkmaar.pdf"] },
  { id: 166, location: "Bergen op Zoom", country: "Netherlands", year: "1421", title: "Discarded Hosts Found Soaked in Blood", description: "On the Sunday before Pentecost in 1421, a pastor at the Church of Saints Peter and Paul in Bergen op Zoom — reportedly doubting transubstantiation — cast leftover consecrated Hosts into a canal after Mass. Several months later, fishermen recovered the Hosts floating on the water, visibly soaked in coagulated blood. The local bishop approved veneration of the miracle, and devotion was officially restored in the twentieth century with annual commemorative events held to this day.", image: "/netherlands4.png", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 167, location: "Boxmeer", country: "Netherlands", year: "1400", title: "Doubting Priest Witnesses Blood from Chalice", description: "In 1400, Father Arnoldus Groen was celebrating Mass at the Church of Saints Peter and Paul in Boxmeer when he was struck by a doubt about the Real Presence; immediately, the consecrated wine began to bubble up and overflow from the chalice onto the corporal, at which point the priest begged God's forgiveness and the bleeding ceased. The blood that had fallen on the corporal coagulated into a lump approximately the size of a walnut, which remains visibly unchanged in Boxmeer today. In 2000, Pope John Paul II elevated the Church of Saint Peter in Boxmeer to the rank of a basilica.", image: "/netherlands3.png", sources: ["https://www.miracolieucaristici.org/en/download/boxmeer.pdf"] },
  { id: 168, location: "Boxtel", country: "Netherlands", year: "1380", title: "Spilled Chalice Stains Corporal with Blood", description: "Around 1380, Father Eligius van der Aker was celebrating Mass in Boxtel when he accidentally overturned the chalice containing consecrated white wine; the wine immediately changed into blood, staining both the corporal and the altar cloth. A decree issued in 1380 by Cardinal Pileus is among the most authoritative documents attesting to the miracle. The blood-stained corporal remained in Boxtel, while the altar cloth was given to the town of Hoogstraten; both relics continue to be venerated in their respective towns.", image: "/netherlands5.png", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 169, location: "Breda", country: "Netherlands", year: "1300", title: "Stolen Host Found Intact Hidden Under Dirt", description: "On June 24, 1300, a soldier pillaging the area stole a consecrated Host; it was later discovered by a local farmer named Jan Bautoen, perfectly intact and hidden beneath a clump of dirt. The Bishop of Liège conducted an official investigation, leaving one of the most authoritative ecclesiastical documents connected with the event. A chapel was built at the site in commemoration, and the story is memorialized in paintings preserved in the local church.", image: "/bel9.png", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 170, location: "Meerssen", country: "Netherlands", year: "1222", title: "Blood Drips from Host; Relic Survives Fire", description: "In 1222, during Sunday Mass at the Benedictine church in Meerssen, blood began to drip from the large consecrated Host onto the corporal and was recognized by ecclesiastical authorities. In 1465, when attackers set fire to the church, a local farmer managed to rescue the blood-stained relic, which emerged from the fire completely unharmed. In 1938, Pope Pius XI elevated the church to the Basilica of the Blessed Sacrament; the relics of the Host and blood-stained corporal remain in the basilica and are carried in procession each year during the octave of Corpus Christi.", image: "/neth9.png", sources: ["https://www.miracolieucaristici.org/en/download/meerssen.pdf"] },

  // ── Poland — additional entry ──
  { id: 171, location: "Głotowo", country: "Poland", year: "1290", title: "Host Preserved Through Lithuanian Invasion", description: "During a Lithuanian invasion in 1290, a local priest buried a ciborium containing a consecrated Host in a field to protect it; the village and church were razed. Years later, a farmer plowing the field discovered the ciborium when his oxen inexplicably stopped and bowed to the ground, and the Host was found emanating bright light. When the Host was brought to a nearby church it miraculously reappeared at the original site, and a church dedicated to Corpus Christi was built there; the shrine was consecrated by Bishop Krzysztof Potocki in 1726 and continues to draw pilgrims.", image: "/poland2.png", sources: ["https://www.miracolieucaristici.org/en/download/glotowo.pdf"] },

  // ── Spain — additional entries ──
  { id: 172, location: "Alboraya", country: "Spain", year: "1348", title: "Three Fish Return Hosts to Priest", description: "In 1348, during the Black Death, a priest lost a coffer of consecrated Hosts when his mule slipped crossing a gully near Valencia, scattering the Hosts in the current. Three fish surfaced with their heads above water, each holding one Host at the tip of its mouth; motionless, they swam to the chalice the priest held over the water and deposited each Host inside before swimming away. The local bishop officially recognized the miracle; historical documents are preserved in the Valencia diocesan archives, and the site is marked by the Ermita dels Peixets, built in 1907.", image: "/spain5.png", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 173, location: "Alcoy", country: "Spain", year: "1568", title: "Christ Child Statue Points to Hidden Hosts", description: "On January 29, 1568, a cloth-shearer named Joan Prats broke into his parish church in Alcoy and stole a silver ciborium containing forty consecrated Hosts and a reliquary, hiding them under rocks beneath his staircase. When the theft was discovered, a statuette of the Christ Child in a neighboring home was seen to lean over and point to the hiding place, directing authorities to the stolen items. The thief's house was converted into an oratory, and each year on January 31 the people of Alcoy hold the Procession of the Miraculous Baby Jesus to commemorate the event.", image: "/spain6.png", sources: ["https://www.miracolieucaristici.org/en/download/alcoy.pdf"] },
  { id: 174, location: "Caravaca de la Cruz", country: "Spain", year: "1231", title: "Angels Deliver Cross During Captive Mass", description: "In 1231, the captive Christian priest Ginés Pérez Chirinos was asked by the Muslim ruler Zeyt-Abuzeyt to celebrate Mass so he could witness the Christian rite; discovering there was no crucifix for the altar, two angels appeared from heaven carrying a Cross and placed it before vanishing. During the consecration, the ruler reportedly saw a vision of a radiant child in the Host and, along with his family, converted to Christianity. The relic of the Vera Cruz is still enshrined at the Basilica of Caravaca de la Cruz, recognized by Pope John Paul II as one of six Holy Cities.", image: "/spain7.png", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 175, location: "Cimballa", country: "Spain", year: "1370", title: "Host Becomes Flesh, Blood Soaks Linen", description: "In 1370, the pastor of Cimballa in Aragon, Father Don Tommaso, had long doubted the Real Presence; at the moment of consecration during a Sunday Mass, the Host transformed into flesh and blood began to flow, saturating the altar linen. Overcome with remorse, Father Tommaso later retired to a monastery to spend the rest of his life in penance. The blood-stained corporal, housed in a reliquary crafted in 1594, is exposed each September 12 — the event is known locally as the 'Most Holy Doubtful Mystery.'", image: "/spain8.png", sources: ["https://www.miracolieucaristici.org/en/download/cimballa.pdf"] },
  { id: 176, location: "Girona", country: "Spain", year: "1297", title: "Host Transforms to Flesh in Priest's Mouth", description: "In 1297 in Gerona (Girona), Catalonia, a priest celebrating Mass was seized by doubt about the Real Presence; at the moment of Communion the priest found himself unable to swallow the Host, which had transformed into flesh in his mouth. The priest confessed his doubt, and the piece of flesh was officially preserved and venerated as a relic. It was kept until it was destroyed in 1936 during the Spanish Civil War.", image: "/spain9.png", sources: ["https://www.miracolieucaristici.org/en/download/gerona.pdf"] },
  { id: 177, location: "El Escorial", country: "Spain", year: "1572", title: "Desecrated Host Bleeds, Preserved for Centuries", description: "In 1572 in Gorkum (Holland), followers of Zwingli removed consecrated Hosts from a cathedral's tabernacle and one heretic stamped on a Host with spiked boots, piercing it in three places; blood immediately began to seep from each wound, and witnessing the miracle, the perpetrator converted on the spot. Hidden by Franciscans and moved through Antwerp and Vienna, the Host arrived at the court of King Philip II of Spain around 1592. The incorrupt, bleeding Host is venerated to this day in the sacristy of the Royal Monastery of San Lorenzo de El Escorial near Madrid, displayed publicly twice a year.", image: "/spain10.png", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 178, location: "Ivorra", country: "Spain", year: "1010", title: "Wine Transforms to Blood, Flows onto Altar", description: "In 1010, the parish priest of Ivorra in Catalonia, Father Bernat Oliver, doubted transubstantiation; during Mass, the wine in the chalice converted entirely into blood that overflowed onto the altar cloth and spilled to the floor. Bishop Saint Ermengol of Urgell traveled to Ivorra to investigate, then carried the chalice and blood-stained cloth to Rome where Pope Sergius IV issued a Pontifical Bull certifying the miracle. The Sacred Relics are still preserved in a Gothic reliquary from 1426 in the parish church of Sant Cugat in Ivorra; the miracle is commemorated annually as 'la Santa Duda' ('the Holy Doubt').", image: "/spain11.png", sources: ["https://www.miracolieucaristici.org/en/download/ivorra.pdf"] },
  { id: 179, location: "Moncada", country: "Spain", year: "1392", title: "Child Identifies the True Host", description: "On Christmas Day 1392, a five-year-old girl named Inés, attending Mass in Moncada, saw the Christ Child appear in the consecrated Host; the priest celebrating Mass had privately doubted the validity of his ordination during the Western Schism. The following day the priest presented her with both a consecrated and unconsecrated host, and she correctly identified the sacred one, dispelling his doubts. The miracle is documented in the Anales Eclesiasticos of Fr. Odorico Raynaldi and in the city archives of Moncada.", image: "/spain12.png", sources: ["https://www.miracolieucaristici.org/en/download/moncada.pdf"] },
  { id: 180, location: "Montserrat", country: "Spain", year: "1657", title: "Father Released from Purgatory at Mass", description: "At the Benedictine Monastery of Our Lady of Montserrat, a grieving girl asked the Abbot to celebrate three Masses for her deceased father's soul. During the first Mass she saw her father surrounded by flames visible only to her; when a tissue was placed where she indicated, it immediately caught fire before the clergy's eyes. By the third Mass her father appeared clothed in white and ascended to heaven at the moment of the Eucharistic celebration, confirming the efficacy of the Mass offered for the dead.", image: "/spain13.png", sources: ["https://www.miracolieucaristici.org/en/download/montserrat.pdf"] },
  { id: 181, location: "O Cebreiro", country: "Spain", year: "1300", title: "Host and Wine Become Flesh and Blood", description: "Around 1300, a Benedictine monk-priest at the mountaintop church of Santa María la Real in O Cebreiro — one of the oldest churches on the Camino de Santiago — had grown cold in his faith and doubted the Real Presence; during the words of consecration, the Host visibly transformed into flesh and the wine into blood, which overflowed the chalice and stained the corporal. In 1486, Queen Isabella of Castile commissioned a precious reliquary to enshrine the miraculous flesh, chalice, and blood-stained corporals during her own pilgrimage; these remain venerated in the church today.", image: "/spain14.png", sources: ["https://www.miracolieucaristici.org/en/download/ocebreiro.pdf"] },
  { id: 182, location: "Onil", country: "Spain", year: "1824", title: "Stolen Hosts Found Perfectly Preserved", description: "On November 5, 1824, a former altar boy named Nicolás Bernabeu stole a monstrance and sacred vessels from the church in Onil; a pyx containing consecrated Hosts was hidden in a field near Tibi, where it was discovered on November 28, 1824 by a woman named Teresa Carbonell. The consecrated Hosts were found completely intact despite weeks of exposure. On November 28, 1943 — exactly 119 years later — the delegate of the Archbishop of Valencia officially confirmed the miraculous incorruption; the Hosts are venerated at the Church of Saint James the Apostle in Onil.", image: "/spain15.png", sources: ["https://www.miracolieucaristici.org/en/download/onil.pdf"] },
  { id: 183, location: "Ponferrada", country: "Spain", year: "1533", title: "Stolen Hosts Shine Light in Blackberry Patch", description: "In 1533, a parishioner stole a silver ciborium containing consecrated Hosts from his church in Ponferrada and discarded it into a blackberry thicket after it became inexplicably heavy when he tried to throw it into the river; witnesses subsequently reported strange lights at night and white doves hovering by day. A miller named Nogaledo discovered the tabernacle while searching for the doves, finding the Hosts intact and emanating light. A chapel was erected on the site, and in 1570 a solemn annual procession was instituted on the octave of Corpus Christi.", image: "/spain16.png", sources: ["https://www.miracolieucaristici.org/en/download/ponferrada.pdf"] },
  { id: 184, location: "Sant Joan de les Abadesses", country: "Spain", year: "1251", title: "Host Incorrupt 175 Years Inside Crucifix", description: "In 1251, a consecrated Host was placed inside a small cavity in the forehead of the Romanesque sculptural group known as the 'Holy Mystery' at the monastery of Sant Joan de les Abadesses in Catalonia, and the cavity was sealed with a silver plaque. In 1426, during restoration work, workers discovered the sealed hollow and found inside, wrapped in white linen, the 175-year-old Host completely incorrupt. The preserved Host, known as 'The Most Holy Mystery of Sant Joan de les Abadesses,' continues to be venerated by pilgrims in the monastery church.", image: "/spain17.png", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
  { id: 185, location: "Valencia", country: "Spain", year: "1437", title: "Holy Chalice of the Last Supper Enshrined", description: "The Cathedral of Valencia preserves what tradition identifies as the Holy Chalice (Santo Cáliz) used by Jesus Christ at the Last Supper — an agate cup carved approximately in the 1st–2nd century BC, said to have been brought from Jerusalem to Rome by Saint Peter and entrusted to deacon Saint Lawrence in 258 AD. It was eventually given by King Alfonso V of Aragon to Valencia's Cathedral in 1437, where it has been venerated ever since. Until the 18th century, the chalice was used to hold the consecrated Host during Holy Thursday ceremonies; it is permanently enshrined in the Chapel of the Holy Chalice within the cathedral.", image: "https://upload.wikimedia.org/wikipedia/commons/f/f1/Juan_de_Juanes_002.jpg", sources: ["https://www.miracolieucaristici.org/en/download/valencia.pdf", "https://en.wikipedia.org/wiki/Holy_Chalice"] },
  { id: 186, location: "Zaragoza", country: "Spain", year: "1427", title: "Stolen Host Appears as Living Child", description: "In 1427 in Zaragoza, a woman brought a stolen consecrated Host to a Moorish sorcerer; when he opened the box, he found not a Host but a living infant surrounded by radiant light, and every attempt to burn it failed. The Archbishop of Zaragoza organized a solemn procession, and when the miraculous Child was placed on the altar during Mass at the Offertory, the Child disappeared and the consecrated Host reappeared in its place. The event is documented in the Zaragoza town hall archives, and a painting commemorating it hangs in the cathedral.", image: "/spain18.png", sources: ["https://www.miracolieucaristici.org/en/download/zaragoza.pdf"] },

  // ── Martinique ──
  { id: 187, location: "Morne-Rouge", country: "Martinique", year: "1902", title: "Sacred Heart Appears During Volcanic Eruption", description: "On May 8, 1902 (Ascension Day), as Mount Pelée erupted and destroyed the nearby city of Saint-Pierre, the population of Morne-Rouge gathered in their parish church for Mass and Eucharistic Adoration. During exposition of the Blessed Sacrament, numerous witnesses reported seeing an image of Jesus displaying His Sacred Heart crowned with thorns appearing within the Host. The village was spared that day; the event was recounted publicly at the Eucharistic Congress of Angoulême in 1904.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },

  // ── Réunion ──
  { id: 188, location: "Saint-André", country: "Réunion", year: "1902", title: "Face of Christ Seen in the Host", description: "On January 26, 1902, during the Forty Hours devotion at the parish church of Saint-André on the island of La Réunion, Abbot Henry Lacombe observed a luminous halo around the monstrance followed by the face of Christ crowned with thorns appearing on the Host. The vision evolved over several hours — the face becoming animated before culminating in the image of a crucifix covering the entire Host — and thousands of witnesses from the town and the capital Saint-Denis confirmed the phenomenon. Abbot Lacombe publicly recounted the event at the Eucharistic Congress of Angoulême in 1904.", sources: ["https://www.miracolieucaristici.org/en/liste/list.html"] },
];
